mod core;
#[path="../setup/fast.rs"]mod fast;
#[path="../multi/algebra.rs"]mod algebra;
#[allow(dead_code)]#[path="../action-consensus/ring.rs"]mod ring;
use hec_native_ic::{counted,fp::Fp,jac::{Curve,Div},poly::Poly,rng::Rng};
use std::{collections::BTreeMap,fs};
fn run(c:&Curve,pt:(u64,u64),d:&Div,t:&Div,ell:u64,sm:u64,gate:bool,consensus:bool)->Vec<core::Trace>{let mut out=vec![];for seed in 1..=3{let trace=core::solve(c,pt,d,t,ell,sm,seed,gate,consensus);let done=trace.answer.is_some();out.push(trace);if done{break}}out}
fn qualify(c:&Curve,d:&Div,t:&Div,ell:u64,lambda:u64,traces:&[core::Trace]){let r=ring::Ring::new(ell);for trace in traces{let seed=c.place(trace.points[1].0,trace.points[1].1);for(&p,h)in trace.points.iter().zip(&trace.labels){let v=h.map(|x|r.eval(x,lambda));assert_eq!(c.place(p.0,p.1),c.add(&c.add(&c.mul(t,v[0]),&c.mul(&seed,v[1])),&c.mul(d,v[2])));}if let Some((l,k))=trace.answer{if let Some(l)=l{assert_eq!(l,lambda);}assert_eq!(c.mul(d,k),*t);}}}
fn main(){counted::disable();let mut old=BTreeMap::new();for l in fs::read_to_string("research/hec_residual_span_20261116/lazy-cyclotomic-cold/CONTROL.tsv").unwrap().lines().skip(1){let v:Vec<_>=l.split('\t').collect();if v[4]!="1"{continue}let n=|i:usize|v[i].parse::<u64>().unwrap();old.insert((n(0),n(1),n(2),n(3),n(5)),v[12].split(',').map(|x|x.parse::<u64>().unwrap()).collect::<Vec<_>>());}
println!("p\tsm\tcase\trep\tarm\tmodulus\tk\texpected\tattempts\trows\tscans\tvisits\tsurvivors\tcounts");let(mut calls,mut incomplete,mut replayed,mut multi_action)=(0,0,0,0);
for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let(fb,_,a)=fast::prepare(&c);let(_,_,degree,lambda)=algebra::certificate(&a,ell);assert_eq!(degree,1);let lambda=lambda.unwrap();let pt=fb[0];let base=c.place(pt.0,pt.1);let mut rng=Rng::new(2026113000^p);
for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let expected=1+rng.below(ell-1);let target=c.mul(&d,expected);let gates=[run(&c,pt,&d,&target,ell,sm,true,false),run(&c,pt,&d,&target,ell,sm,true,true)];for traces in &gates{qualify(&c,&d,&target,ell,lambda,traces);}let mut prior=BTreeMap::new();for rep in 0..2{for n in 0..2{let arm=if rep==0{n}else{1-n};counted::reset();let traces=run(&c,pt,&d,&target,ell,sm,false,arm==1);assert_eq!(traces,gates[arm]);let counts=counted::snapshot();counted::disable();let last=traces.last().unwrap();let k=last.answer.map(|x|x.1);if let Some(k)=k{assert_eq!(k,expected);assert_eq!(c.mul(&d,k),target);if arm==1&&last.survivors>1{multi_action+=1;}}else{incomplete+=1;}let sig=(traces.clone(),counts.clone());if rep==1{assert_eq!(prior[&arm],sig);}else{prior.insert(arm,sig);}let rows:usize=traces.iter().map(|x|x.rows).sum();let scans:usize=traces.iter().map(|x|x.scans).sum();let visits:usize=traces.iter().map(|x|x.visits).sum();for(modulus,v)in counts{assert_eq!(v[8],2*v[7]+v[5]+v[6]);if arm==0{assert_eq!(v.as_slice(),old[&(p,sm,case,rep,modulus)].as_slice());replayed+=1;}println!("{p}\t{sm}\t{case}\t{rep}\t{arm}\t{modulus}\t{}\t{expected}\t{}\t{rows}\t{scans}\t{visits}\t{}\t{}",k.map_or("none".into(),|x|x.to_string()),traces.len(),last.survivors,v.iter().map(u64::to_string).collect::<Vec<_>>().join(","));}calls+=1;}}}}
}assert_eq!(calls,48);assert_eq!(replayed,48);eprintln!("calls={calls} incomplete_calls={incomplete} strict_modulus_vectors_replayed={replayed} consensus_multi_action_calls={multi_action} exact_repeats=true all_label_and_final_target_checks=true changed_validation_contract_explicit=true");}
